package ru.neverland.townycrime;
import java.util.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import org.bukkit.plugin.java.JavaPlugin;
import ru.neverland.core.*;
/** Read-only lists, live permissions and explicit commands for acknowledged mutations. */
public final class CrimePatrolMenu implements Listener {
    private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd.MM HH:mm 'МСК'").withZone(ZoneId.of("Europe/Moscow"));
    private final JavaPlugin plugin;private final CrimePatrolService service;private final CrimeMenu parent;
    static final class View implements InventoryHolder{final UUID viewer,town;final boolean incidents;final int page;Inventory inventory;View(UUID viewer,UUID town,boolean incidents,int page){this.viewer=viewer;this.town=town;this.incidents=incidents;this.page=page;}public Inventory getInventory(){return inventory;}}
    public CrimePatrolMenu(JavaPlugin plugin,CrimePatrolService service,CrimeMenu parent){this.plugin=plugin;this.service=service;this.parent=parent;}
    public void open(Player player,UUID town,boolean incidents,int page){try(var guard=SuiteState.guard()){if(!service.allowed(player,town))throw new IllegalArgumentException("Нет доступа к журналу города.");service.refresh(town);var snapshot=service.report(town);var rows=list(snapshot.get(incidents?"incidents":"rows"));int count=Math.max(1,(rows.size()+27-1)/27);page=Math.max(0,Math.min(page,count-1));var view=new View(player.getUniqueId(),town,incidents,page);view.inventory=MenuStyle.inventory(plugin,view,54,incidents?"Городские происшествия":"Районные патрули");
        view.inventory.setItem(4,item(Material.WRITABLE_BOOK,incidents?"Подтверждённые происшествия":"Задания городской стражи",incidents?"Городские события без установленного виновника.":"Назначения и сообщения участников, без зарплаты.","Последние 256 записей; история сохраняется.","Патруль не снижает преступность автоматически."));
        view.inventory.setItem(45,item(Material.ARROW,"К преступности города"));view.inventory.setItem(49,item(Material.CLOCK,"Обновить"));view.inventory.setItem(46,item(incidents?Material.SHIELD:Material.BOOK,incidents?"Патрули":"Происшествия"));
        if(!Boolean.TRUE.equals(snapshot.get("available")))view.inventory.setItem(22,item(Material.BARRIER,"Журнал временно недоступен",String.valueOf(snapshot.getOrDefault("issue","Сведения готовятся")),"Городские ресурсы и штрафы не изменены."));
        else{if(!String.valueOf(snapshot.getOrDefault("issue","")).isBlank())view.inventory.setItem(8,item(Material.GRAY_DYE,"Районы недоступны",String.valueOf(snapshot.get("issue")),"Сохранённые отчёты остаются доступны."));if(rows.isEmpty())view.inventory.setItem(22,item(Material.BOOK,"Записей пока нет"));for(int i=page*27;i<Math.min(rows.size(),(page+1)*27);i++){var row=map(rows.get(i));int slot=9+i-page*27;var lore=new ArrayList<String>();lore.add("ID: "+row.get("id"));lore.add("Дата: "+date(row.get("created")));if(incidents){String kind="BURGLARY".equals(row.get("kind"))?"Кража со склада":"Вымогательство";lore.add(kind);if("BURGLARY".equals(row.get("kind")))lore.add(CrimeMenu.resource(String.valueOf(row.get("resource")))+": "+CrimeMenu.number(((Number)row.get("amount")).longValue()/1000.0));lore.add("Событие относится ко всему городу.");lore.add("Место и виновник не определены.");lore.add("Связь с существующим делом:");lore.add("/justice evidence <дело> incident <ID>");view.inventory.setItem(slot,item(Material.PAPER,kind,lore.toArray(String[]::new)));}
        else{lore.add("Район: "+row.get("districtName")+" ("+row.get("district")+")");lore.add("Исполнитель: "+row.get("workerName"));lore.add("Состояние: "+phase(String.valueOf(row.get("phase"))));if(!Boolean.TRUE.equals(row.get("districtReady")))lore.add("Район удалён либо сведения недоступны.");String report=String.valueOf(row.get("report"));if(!report.isEmpty())lore.addAll(wrap(report));lore.add("Отчёт — заявление участника, не доказательство вины.");lore.add("/t crime report <ID> <текст>");view.inventory.setItem(slot,item("ASSIGNED".equals(row.get("phase"))?Material.SHIELD:Material.PAPER,String.valueOf(row.get("districtName")),lore.toArray(String[]::new)));}}
        if(page>0)view.inventory.setItem(48,item(Material.ARROW,"Предыдущая страница"));if(page+1<count)view.inventory.setItem(50,item(Material.ARROW,"Следующая страница"));
        if(!incidents){var areas=list(snapshot.get("districts"));var help=new ArrayList<String>();help.add("Отчёт сдавайте в назначенном районе:");help.add("/t crime report <ID> <текст 5–300 символов>");help.add("Районы города:");for(Object raw:areas.stream().limit(12).toList()){var area=map(raw);help.add(area.get("id")+" — "+area.get("name"));}if(areas.size()>12)help.add("Полный список: /t districts");if(service.manager(player,town)){help.add("/t crime patrol <район> <житель>");help.add("/t crime cancelpatrol <ID> <причина>");}view.inventory.setItem(52,item(Material.FEATHER,"Как назначить патруль и сдать отчёт",help.toArray(String[]::new)));}}
        player.openInventory(view.inventory);
    }}
    @EventHandler public void click(InventoryClickEvent event){if(!(event.getView().getTopInventory().getHolder()instanceof View view))return;event.setCancelled(true);if(!(event.getWhoClicked()instanceof Player player)||!player.getUniqueId().equals(view.viewer))return;int slot=event.getRawSlot();if(slot<0||slot>=54)return;SuiteScheduler.entity(plugin,player,()->{if(player.getOpenInventory().getTopInventory()!=view.inventory)return;if(!service.allowed(player,view.town)){player.closeInventory();return;}try{if(slot==45)parent.open(player,view.town,null);else if(slot==46)open(player,view.town,!view.incidents,0);else if(slot==48||slot==49||slot==50)open(player,view.town,view.incidents,view.page+(slot==48?-1:slot==50?1:0));else if(slot==52)help(player);}catch(Exception error){player.sendMessage("§cПатрули: "+error.getMessage());}});}
    @EventHandler public void drag(InventoryDragEvent event){if(event.getView().getTopInventory().getHolder()instanceof View)event.setCancelled(true);}
    public static void help(Player player){player.sendMessage(ru.neverland.core.EditableMessages.text(CrimePatrolMenu.class, "§e/t crime patrols §7— районные задания; incidents — журнал событий"));player.sendMessage(ru.neverland.core.EditableMessages.text(CrimePatrolMenu.class, "§e/t crime report <ID> <текст> §7— отчёт в назначенном районе"));player.sendMessage(ru.neverland.core.EditableMessages.text(CrimePatrolMenu.class, "§e/t crime patrol <район> <житель> §7— назначает мэр или уполномоченный суд"));player.sendMessage(ru.neverland.core.EditableMessages.text(CrimePatrolMenu.class, "§e/t crime cancelpatrol <ID> <причина> §7— отмена без штрафов"));player.sendMessage(ru.neverland.core.EditableMessages.text(CrimePatrolMenu.class, "§7Сообщения сохраняются после подтверждения. Автоматических выплат или обвинений нет."));}
    static boolean holds(Inventory inventory){return inventory!=null&&inventory.getHolder()instanceof View;}
    static String phase(String value){return switch(value){case "ASSIGNED"->"Назначен";case "COMPLETED"->"Отчёт сдан";case "CANCELLED"->"Отменён";default->"Недоступно";};}
    private static String date(Object value){return value instanceof Number number?DATE.format(Instant.ofEpochMilli(number.longValue())):"неизвестно";}
    private static List<String> wrap(String text){var result=new ArrayList<String>();for(int start=0;start<text.length();start+=48)result.add(text.substring(start,Math.min(start+48,text.length())));return result;}
    @SuppressWarnings("unchecked")private static Map<String,Object> map(Object value){return value instanceof Map<?,?> map?(Map<String,Object>)map:Map.of();}private static List<?> list(Object value){return value instanceof List<?> list?list:List.of();}
    private static ItemStack item(Material material,String name,String... lore){var stack=new ItemStack(material);var meta=stack.getItemMeta();meta.setDisplayName(MenuStyle.nameLegacy("&b"+name));meta.setLore(MenuStyle.loreStrings(Arrays.stream(lore).map(s->"&7"+s).toList()));meta.addItemFlags(ItemFlag.HIDE_ATTRIBUTES);stack.setItemMeta(meta);return stack;}
}
